const CFG = {
  project_id: '9933660066825e9a8005c8.58526829',
  model: 'gpt-4.1',
  batch: 25,
  locales: ['es','it','fr','pt','ro','pl','lv','lt','de','nl','da','no','sv','et','id','ms','ko','th'],
  groups: ['test_questions::occ','test_questions::ocd','test_questions::ps','test_questions::so','(untagged)','test_questions::anxiety','test_questions::bt','test_questions::et','test_questions::fa','test_questions::ma','test_questions::nd']
};
const BASE = 'https://api.lokalise.com/api2';
const qs = 'include_translations=1&disable_references=1&limit=500&pagination=cursor';
CFG.url = BASE + '/projects/' + CFG.project_id + '/keys?' + qs;
CFG.put_url = BASE + '/projects/' + CFG.project_id + '/keys';
return [{ json: CFG }];

const C = $('Config').first().json;
const RULES = {"es":{"name":"Spanish","period":true,"case":"sentence","dev":"slash","dev_ex":"crítico/a, cómodo/a","fem":"crítica, cómoda","masc":"crítico, cómodo","notes":"Never voseo. Prefer 'me siento' constructions. Drop the redundant subject pronoun 'yo'."},"it":{"name":"Italian","period":true,"case":"sentence","dev":"slash","dev_ex":"visto/a, sicuro/a","fem":"vista, sicura","masc":"visto, sicuro","notes":"Drop the subject pronoun 'io'. Prefer 'mi sento' over 'sono'."},"fr":{"name":"French","period":true,"case":"sentence","dev":"paren","dev_ex":"aimé(e), prêt(e)","fem":"aimée, prête","masc":"aimé, prêt","notes":"Keep 'je'. Plain spaces only."},"pt":{"name":"Portuguese (Brazil)","period":true,"case":"sentence","dev":"paren","dev_ex":"motivado(a), cansado(a)","fem":"motivada, cansada","masc":"motivado, cansado","notes":"Brazilian usage. Drop the subject pronoun 'eu' where natural."},"ro":{"name":"Romanian","period":true,"case":"sentence","dev":"slash","dev_ex":"perfecționist/ă, singur/ă","fem":"perfecționistă, singură","masc":"perfecționist, singur","notes":"Drop the subject pronoun 'eu'. Use dative reflexive 'îmi' constructions."},"pl":{"name":"Polish","period":true,"case":"sentence","dev":"paren-hyphen","dev_ex":"kochany(-a), obawiałem(-am)","fem":"kochana, obawiałam","masc":"kochany, obawiałem","notes":"Drop the subject pronoun 'ja'. Past-tense verb forms are gendered - treat them exactly like adjectives."},"lv":{"name":"Latvian","period":true,"case":"sentence","dev":"paren-hyphen","dev_ex":"mīlēts(-ta), pārliecināts(-ta)","fem":"mīlēta, pārliecināta","masc":"mīlēts, pārliecināts","notes":"Drop the subject pronoun 'es' where natural."},"lt":{"name":"Lithuanian","period":true,"case":"sentence","dev":"masc-default","dev_ex":"atlikdamas","fem":"atlikdama, pavargusi","masc":"atlikdamas, pavargęs","notes":"Participles and adjectives are gendered; the corpus uses no slash or bracket device."},"de":{"name":"German","period":true,"case":"sentence","dev":"none","dev_ex":"","fem":"","masc":"","notes":"Neue deutsche Rechtschreibung, ss written as the sharp s where correct. No gender star or colon. Add no quotation marks."},"nl":{"name":"Dutch","period":true,"case":"sentence","dev":"none","dev_ex":"","fem":"","masc":"","notes":"Prefer 'ik voel me' over nominal constructions."},"da":{"name":"Danish","period":true,"case":"sentence","dev":"none","dev_ex":"","fem":"","masc":"","notes":"First person carries no gender marking."},"no":{"name":"Norwegian","period":true,"case":"sentence","dev":"none","dev_ex":"","fem":"","masc":"","notes":"Bokmal."},"sv":{"name":"Swedish","period":true,"case":"sentence","dev":"none","dev_ex":"","fem":"","masc":"","notes":"First person carries no gender marking."},"et":{"name":"Estonian","period":true,"case":"sentence","dev":"none","dev_ex":"","fem":"","masc":"","notes":"No grammatical gender. Drop 'ma' or 'mina' where natural."},"id":{"name":"Indonesian","period":true,"case":"sentence","dev":"none","dev_ex":"","fem":"","masc":"","notes":"No grammatical gender. Use 'saya', never 'aku'."},"ms":{"name":"Malay","period":true,"case":"sentence","dev":"none","dev_ex":"","fem":"","masc":"","notes":"No grammatical gender. Use 'saya'."},"ko":{"name":"Korean","period":true,"case":"none","dev":"none","dev_ex":"","fem":"","masc":"","notes":"No letter case. The corpus uses the plain declarative style, not polite endings. Output runs about half the English character count."},"th":{"name":"Thai","period":false,"case":"none","dev":"none","dev_ex":"","fem":"","masc":"","notes":"No final full stop and no letter case. Use the first-person pronoun the corpus uses. No politeness particles."}};
const GENDER = { 'test_questions::fa': 'female', 'test_questions::ma': 'male' };

const keys = [];
for (const p of $input.all()) {
  const b = (p.json && p.json.body) || {};
  if (!Array.isArray(b.keys)) continue;
  for (const k of b.keys) {
    const kn = k.key_name;
    const nm = typeof kn === 'string' ? kn : ((kn && (kn.web || kn.other)) || '');
    if (nm.indexOf('_questions.') === -1) continue;
    const tags = k.tags || [];
    const gs = tags.filter(function (t) { return t.indexOf('questions::') !== -1 || t === 'questions'; });
    const t = {};
    let en = '';
    for (const tr of (k.translations || [])) {
      let x = tr.translation;
      if (x && typeof x === 'object') x = JSON.stringify(x);
      x = (x === null || x === undefined) ? '' : String(x);
      if (tr.language_iso === 'en') { en = x; continue; }
      if (x.trim()) t[tr.language_iso] = x;
    }
    keys.push({ id: k.key_id, n: nm, g: gs.length ? gs[0] : '(untagged)', tags: tags, en: en, t: t });
  }
}

const out = [];
const stats = { keys_scanned: keys.length, batches: 0, strings: 0, per_locale: {} };
for (const L of C.locales) {
  const R = RULES[L];
  if (!R) continue;
  const corpus = keys.filter(function (k) { return k.t[L] && k.t[L].trim() !== k.en.trim(); });
  const shots = [];
  const step = Math.max(1, Math.floor(corpus.length / 12));
  for (let i = 0; i < corpus.length && shots.length < 12; i += step) {
    shots.push('EN: ' + corpus[i].en + String.fromCharCode(10) + 'TARGET: ' + corpus[i].t[L]);
  }
  let n = 0;
  for (const G of C.groups) {
    const mode = GENDER[G] || 'neutral';
    let gl;
    if (mode === 'female') gl = 'The respondent is FEMALE (this is the female archetype test). Use feminine agreement throughout, e.g. ' + R.fem + '. Do NOT use any dual-gender notation.';
    else if (mode === 'male') gl = 'The respondent is MALE (this is the male archetype test). Use masculine agreement throughout, e.g. ' + R.masc + '. Do NOT use any dual-gender notation.';
    else if (R.dev === 'slash' || R.dev === 'paren' || R.dev === 'paren-hyphen') gl = 'Respondent gender is unknown. Use exactly the dual-gender notation the reference examples use: ' + R.dev_ex + '.';
    else if (R.dev === 'masc-default') gl = 'Respondent gender is unknown. Use the masculine form, as the reference examples do.';
    else gl = 'No gender marking is needed in ' + R.name + '.';

    const lines = [
      'You are a professional ' + R.name + ' translator working on psychometric self-report tests for Personality.co.',
      'Translate each English item into ' + R.name + '. Each item is a first-person statement the user rates on an agreement scale.',
      '',
      'RULES',
      '- Keep every item a declarative statement. Never turn it into a question.',
      R.period ? '- End every statement with a full stop.' : '- Do NOT add a final full stop.',
      R.case === 'sentence' ? '- Sentence case: capitalise the first letter only, plus proper nouns.' : '- The script has no letter case.',
      '- ' + gl,
      '- Avoid first-person possessive determiners wherever ' + R.name + ' offers a natural alternative (definite article, reflexive, or bare noun). Never force it at the cost of naturalness.',
      '- Plain text only. No placeholders, no HTML, no added quotation marks, no brand names.',
      '- Match the register, rhythm and length of the reference examples.',
      '- ' + R.notes,
      '',
      'REFERENCE EXAMPLES (existing human translations from the same test battery - match this style exactly)',
      shots.join(String.fromCharCode(10)),
      '',
      'Return ONLY JSON in this shape: {"t":[{"i":123,"s":"translation"}]} with one entry per input id, in the same order, and nothing else.'
    ];
    const sys = lines.filter(function (x) { return x !== ''; }).join(String.fromCharCode(10));

    const todo = keys.filter(function (k) { return k.g === G && k.en.trim() && !k.t[L]; });
    for (let i = 0; i < todo.length; i += C.batch) {
      const chunk = todo.slice(i, i + C.batch);
      out.push({
        json: {
          locale: L,
          group: G,
          mode: mode,
          items: chunk.map(function (c) { return { i: c.id, en: c.en, n: c.n, tags: c.tags }; }),
          body: {
            model: C.model,
            temperature: 0.3,
            response_format: { type: 'json_object' },
            messages: [
              { role: 'system', content: sys },
              { role: 'user', content: JSON.stringify(chunk.map(function (c) { return { i: c.id, en: c.en }; })) }
            ]
          }
        }
      });
      stats.batches++;
      stats.strings += chunk.length;
      n += chunk.length;
    }
  }
  stats.per_locale[L] = n;
}
if (!out.length) throw new Error('Plan produced no batches: ' + JSON.stringify(stats));
out[0].json.stats = stats;
return out;

const plan = $('Plan').all();
const res = $input.all();
const errors = [];
const rowsOut = [];
const byKey = {};
const PERIOD_OFF = { th: 1 };
const FLOOR = { ko: 0.18, th: 0.25 };

if (plan.length !== res.length) errors.push('item count mismatch: plan ' + plan.length + ' vs responses ' + res.length);

for (let b = 0; b < res.length; b++) {
  const p = plan[b] ? plan[b].json : null;
  const r = res[b] ? res[b].json : null;
  if (!p) { errors.push('batch ' + b + ': no plan item'); continue; }
  const tag = p.locale + '/' + p.group + '#' + b;
  if (!r || r.error) { errors.push(tag + ': request failed ' + JSON.stringify(r && r.error).slice(0, 200)); continue; }
  let content = '';
  try { content = r.choices[0].message.content; } catch (e) { errors.push(tag + ': no content'); continue; }
  let parsed;
  try { parsed = JSON.parse(content); } catch (e) { errors.push(tag + ': content not JSON'); continue; }
  const arr = parsed.t || parsed.translations || [];
  if (!Array.isArray(arr)) { errors.push(tag + ': no array'); continue; }
  const map = {};
  for (const e of arr) { if (e && e.i !== undefined) map[String(e.i)] = String(e.s === undefined ? '' : e.s); }
  for (const it of p.items) {
    const s = map[String(it.i)];
    if (s === undefined) { errors.push(tag + ' key ' + it.i + ': missing from response'); continue; }
    const v = s.trim();
    if (!v) { errors.push(tag + ' key ' + it.i + ': empty'); continue; }
    if (v === it.en.trim()) { errors.push(tag + ' key ' + it.i + ': identical to English'); continue; }
    const ratio = v.length / Math.max(it.en.length, 1);
    const floor = FLOOR[p.locale] || 0.35;
    if (ratio < floor || ratio > 3) { errors.push(tag + ' key ' + it.i + ': length ratio ' + ratio.toFixed(2)); continue; }
    if (v.indexOf('{') !== -1 || v.indexOf('<') !== -1) { errors.push(tag + ' key ' + it.i + ': contains markup'); continue; }
    const wantPeriod = !PERIOD_OFF[p.locale];
    const hasPeriod = v.slice(-1) === '.';
    let fixed = v;
    if (wantPeriod && !hasPeriod && v.slice(-1) !== '?' && v.slice(-1) !== '!') fixed = v + '.';
    if (!wantPeriod && hasPeriod) fixed = v.replace(/\.+$/, '');
    if (!byKey[it.i]) byKey[it.i] = { key_id: it.i, n: it.n, tags: it.tags.slice(), tr: {} };
    byKey[it.i].tr[p.locale] = fixed;
    rowsOut.push({ key_id: it.i, n: it.n, group: p.group, mode: p.mode, locale: p.locale, en: it.en, target: fixed });
  }
}

const ids = Object.keys(byKey);
const putKeys = [];
for (const id of ids) {
  const k = byKey[id];
  const tags = k.tags.indexOf('to_review') === -1 ? k.tags.concat(['to_review']) : k.tags;
  const translations = Object.keys(k.tr).map(function (L) {
    return { language_iso: L, translation: k.tr[L], is_unverified: true, is_reviewed: false };
  });
  putKeys.push({ key_id: Number(k.key_id), tags: tags, translations: translations });
}

const out = [];
const summary = { batches: res.length, keys: ids.length, strings: rowsOut.length, errors: errors.length, error_sample: errors.slice(0, 25) };
for (let i = 0; i < putKeys.length; i += 150) {
  out.push({ json: { kind: 'put', part: i / 150, body: { keys: putKeys.slice(i, i + 150) } } });
}
if (!out.length) out.push({ json: { kind: 'put', part: 0, body: { keys: [] } } });
out[0].json.summary = summary;
out[0].json.rows = rowsOut;
return out;

const v = $('Validate').all();
const summary = (v[0] && v[0].json.summary) || {};
const rows = (v[0] && v[0].json.rows) || [];
const writes = [];
for (const r of $input.all()) {
  const j = r.json || {};
  if (j.statusCode !== undefined) writes.push({ statusCode: j.statusCode, keys: (j.body && j.body.keys ? j.body.keys.length : 0), err: j.statusCode === 200 ? '' : JSON.stringify(j.body).slice(0, 300) });
}
const chunks = [];
for (let i = 0; i < rows.length; i += 250) chunks.push({ json: { kind: 'rows', i: i, rows: rows.slice(i, i + 250) } });
return [{ json: { kind: 'summary', summary: summary, writes: writes, wrote: writes.length > 0 } }].concat(chunks);
